programs.haiku:
"""Layer 15 MLP hidden unit 5521 (the down_proj component), read as a plain activation.

What it responds to: the unit goes negative in citation and attribution phrases, the
words that say who said, showed or found something:
  - "by" introducing the agent of a passive verb ("was found by", "shown by", "conducted by");
  - the word right after "according" ("according to [the] ..."), "accordance", and
    after "told", "said", "noted", "shown", "as mentioned/seen/shown" (e.g. "As shown [in]");
  - the speech tag after a closing quote ("...," he said / replied);
  - more weakly, function words (in, the, of, to, as, ",", "(") in general.
Everything else sits near zero, and most of the unit's variance is not captured: its
activation is spread over all tokens and depends on context this short program does not
track. These rules capture the mean level of its negative dips (about 2% of variance).
"""

READS = ()

# words that name a source or refer to what someone said, showed or found
CUES = {
    "according", "accordance", "told", "tells", "said", "says", "noted", "shown", "shows",
    "stated", "argued", "wrote", "reported", "found", "described", "mentioned", "seen",
    "illustrated", "explained", "suggested", "conducted", "discussed", "previously", "above",
}
FUNCTION = {
    "in", "by", "the", "of", "to", "as", "from", "on", "at", "with", "for", "this", "that",
    "a", "an", "and", "(", ",", "his", "its", "our", "my", "[",
}
QUOTE_ENDS = {',"', ',”'}


def step(carry, prefix, upstream):
    ids = prefix.token_ids
    docs = prefix.document_ids
    word = prefix.token_strings[-1].strip().lower()

    def back(k):
        # the token k places back, unless it lies in an earlier document
        if len(ids) <= k or docs[-1 - k] != docs[-1]:
            return ""
        return prefix.token_strings[-1 - k]

    prev, prev2 = back(1).strip().lower(), back(2).strip().lower()
    if back(1) in QUOTE_ENDS:
        value = -1.5
    elif word == "by":
        value = -2.2
    elif prev in {"according", "accordance"} or (prev == "to" and prev2 == "according"):
        value = -3.5
    elif prev in CUES and word in FUNCTION:
        value = -1.0
    elif word in FUNCTION:
        value = -0.15
    else:
        value = -0.05
    return carry, value

"""Layer 15 MLP down_proj, component 5522: a sparse, mostly context-driven component.

Its activation is near 0 (about +/-0.4) on most tokens, with rare large values. Those large
values come from a few recognisable situations, and this program predicts those and nothing else:

- the closing think tag `</think>` that ends the empty reasoning block opening an assistant
  reply: about +5.8;
- the space typed before a figure or table number ("Figure 2", "Table 1"): about -5;
- the diff hunk marker " @@" and form feeds (page breaks): about -10;
- a starred variable in a maths-dataset equation, such as "Suppose 3*n = ..." or
  "Solve -26*n ...", within about 60 tokens of the cue word "Suppose" or "Solve": about -18;
- tool-call markup `<tool_call>` and `</tool_response>`: about +1.

Every other token predicts 0.
"""

READS = ()

THINK_CLOSE = "</think>"
FIGURE_WORDS = {  # a figure or table reference word, with or without its leading space
    "Figure", " Figure", "figure", " figure", "Fig", " Fig",
    "Table", " Table", "table", " table",
}
PAGE_MARKS = {" @@", "\x0c"}
TOOL_TAGS = {"<tool_call>", "</tool_response>"}
MATH_CUES = ("Suppose", "Solve")
WINDOW = 60  # tokens after a math cue word in which starred variables count


def is_starred_variable(token):
    """A single token like '*n': an asterisk followed by one letter."""
    return len(token) == 2 and token[0] == "*" and token[1].isalpha()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    doc = prefix.document_ids[-1]
    # carry: (document id, tokens since the last math cue word); None at a row's start
    if carry is None or carry[0] != doc:
        since_cue = 10**9
    else:
        since_cue = carry[1] + 1
    if any(cue in tok for cue in MATH_CUES):
        since_cue = 0
    in_math = since_cue <= WINDOW

    if tok == THINK_CLOSE:
        value = 5.8
    elif tok == " " and prev in FIGURE_WORDS:
        value = -5.0
    elif tok in PAGE_MARKS:
        value = -10.0
    elif is_starred_variable(tok) and in_math:
        value = -18.0
    elif tok in TOOL_TAGS:
        value = 1.0
    else:
        value = 0.0
    return (doc, since_cue), float(value)

"""Early-document response of one MLP hidden direction in layer 15 (block 15, down_proj).

The component is mostly quiet, but right after a document starts it is strongly
negative: about -7 on the second token when the document's first token is a
word that continues a sentence (leading space, e.g. " it", " the", " of"), about
-4 when the first token is a capitalised word or punctuation, and about -1 when
it is a digit. The response decays with distance k from the document's first
token (k = 1 is the second token) roughly as 1, 0.36, 0.2, 0.12, 0.07, 0.04.
Further into the document it is close to zero, with a small positive drift
(about +0.2) from token 8 to token 63.
"""

READS = ()

# Activation scale by distance k from the document's first token (k = 1: second token).
DECAY = {1: 1.0, 2: 0.36, 3: 0.2, 4: 0.12, 5: 0.07, 6: 0.04}


def first_token_level(text):
    """Activation scale of the second token, from the first token's text."""
    if text.strip()[:1].isdigit():
        return -1.2  # digit start: almost no response
    if text[:1] == " ":
        return -7.5  # a word continuing a sentence
    return -3.8  # capitalised word, punctuation or newline


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        k, level = 0, 0.0
    else:
        k, level = carry[1] + 1, carry[2]
    if k == 0:
        level = first_token_level(prefix.token_strings[-1])
    if k in DECAY:
        value = level * DECAY[k]
    elif 8 <= k < 64:
        value = 0.2  # slight positive drift in the middle of a document
    else:
        value = 0.0
    return (doc, k, level), value

"""Layer 15 MLP unit 5528 (this component reads that one hidden unit).

Its activation is the SwiGLU value of that unit times a fixed scale. The value
depends on context in ways no simple rule captures. This program predicts a
baseline and adjusts it by a few token-shape rules, fit on sampled activations:
brackets and identifier pieces (underscored names, pieces of a word that
continues with no space) push it down, nested code pushes it down, and
newlines and digits push it up.
"""

from collections.abc import Mapping
import regex

READS: tuple[str, ...] = ()

BASE = -0.03
BRACKETS = set("()[]{}")
WORD = regex.compile(r"[\p{L}\p{N}_]")


def is_word(s: str) -> bool:
    return bool(s) and all(WORD.match(c) for c in s)


def step(carry, prefix, upstream: Mapping):
    depth, last_doc = carry if carry is not None else (0, None)
    if prefix.document_ids[-1] != last_doc:
        depth = 0  # a new document starts with no open brackets
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    s = tok.strip()
    v = BASE
    if s and all(c in BRACKETS for c in s):
        v -= 0.28
    if "_" in tok:
        v -= 0.13
    if depth > 0:
        v -= 0.06
    if "\n" in tok:
        v += 0.13
    if s.isdigit():
        v += 0.14
    if is_word(s) and not tok[:1].isspace() and is_word(prev.strip()):
        v -= 0.06  # a word piece that continues the previous token
    for ch in tok:
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth = max(0, depth - 1)
    return (depth, prefix.document_ids[-1]), float(v)

"""A weak word-level proxy for one MLP output component of Qwen3-1.7B (layer 15).

The component's activation is diffuse: which word is present explains only about 3% of its
variance, and the words before it add little. So this program keeps the strongest word-level
tendencies seen in training text, and nothing more:
- positive: emphatic, hype and future-tense words ("big", "great", "more", "will", "'ll",
  "fun", "features", "!"), and CJK characters, which run above average;
- negative: code and testing vocabulary ("test", "import", "function", "code", ...);
- everything else: 0.
The word values are scaled down (about 0.65) to the size that best fits the activations.
"""

import re

READS = ()

HYPE = {
    "big", "great", "more", "some", "will", "fun", "lot", "much", "new", "special",
    "including", "features", "got", "get", "come", "going", "course", "tell", "enjoy",
    "news", "tips", "interesting", "explore", "journey", "adventure",
}
CONTRACTIONS = {"'ll", "’ll", "'re", "’re", "'ve", "’ve"}
EXCLAIM = {"!", "！"}
TECH = {"test", "tests", "import", "function", "code", "algebra", "equation", "calculator", "static", "type", "command", "directory"}
SCALE = 0.65


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    if word in HYPE or word in CONTRACTIONS or word in EXCLAIM:
        base = 1.0
    elif re.search(r"[一-鿿]", tok):
        base = 0.4
    elif word in TECH:
        base = -0.5
    else:
        base = 0.0
    return carry, SCALE * base

"""Clause junctions (layers.15 MLP down_proj, component 5540).

The component fires at the join between two clauses: just after a clause has been
finished and before the next one (or its connective) begins. Three things drive it:

1. A comma, semicolon or other clause separator that closes a clause. The longer the
   clause it closes (counted in tokens since the last boundary), the higher it fires.
   A comma after one or two words, as in a number or name list, stays low. A clause
   that shows a subject pronoun or auxiliary verb fires a bit more.
2. A connective that opens a new clause: "but", "however", "because", "pero", "但" fire
   strongly anywhere. "and", "or", "so" fire strongly only right after a boundary, and
   grow with the length of the clause before them.
3. An opening parenthesis fires moderately.

Everything else sits near zero. Sentence ends reset the clause length.
"""

READS = ()

# Separators that close a clause or list item, Latin and CJK.
CLAUSE_PUNCT = {",", "，", "、", ";", "；"}
# Sentence and line ends: they reset the clause length and never fire.
SENTENCE_END = {".", "!", "?", "。", "！", "？", "\n", "\n\n", ".\n", ":"}
# Connectives that open a new clause wherever they appear.
STRONG = {
    "but", "however", "therefore", "thus", "hence", "because", "whereas", "although",
    "though", "unless", "pero", "mais", "ale", "sino", "但", "而且", "所以", "因此",
    "ので", "なので", "ですが", "から", "けど", "donc", "но", "и",
}
# Coordinators and subordinators: they fire mostly after a long clause.
LINKING = {"and", "or", "so", "then", "while", "which", "since", "yet", "und", "et",
           "并", "而", "且"}
# Weaker connectives, a constant small value.
WEAK = {"which", "when", "if", "than", "as"}
OPEN_PAREN = {"(", "（"}
# Words that show a finite clause: subject pronouns and auxiliary or copula verbs.
FINITE = {"i", "you", "he", "she", "it", "we", "they", "is", "are", "was", "were", "be",
          "has", "have", "had", "can", "will", "would", "should", "could", "do", "does", "did"}


def step(carry, prefix, upstream):
    # carry: (tokens since the last clause or sentence boundary, whether they show a finite clause)
    n, finite = carry or (0, False)
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        n, finite = 0, False
    tok = prefix.token_strings[-1].strip()

    # A separator (or a token ending in one, like '),' or '",') closes a clause.
    if tok in CLAUSE_PUNCT or (len(tok) > 1 and tok[-1] in ",，、"):
        value = 0.3 * min(n, 7)
        if n >= 2:
            value += 0.4 + (1.2 if finite else 0.0)
        return (0, False), value

    if tok in SENTENCE_END:
        return (0, False), 0.0

    if tok in STRONG:
        return (n + 1, finite), 4.0

    if tok in LINKING:
        # right after a boundary it fires strongly; after a short phrase it is weak
        return (n + 1, finite), 3.5 if n == 0 else 0.4 * min(n, 6)

    if tok in WEAK or tok in OPEN_PAREN:
        return (n + 1, finite), 1.2

    # any other token: no firing, but it lengthens the clause and may show a finite verb
    return (n + 1, finite or tok.lower() in FINITE), 0.0

"""Consequence markers and the commas that close conditional clauses.

Activation is negative where a conclusion or result is being introduced:
- on the marker itself: "then", "so", "therefore", "thus", "hence" (after a comma, a link
  word or a sentence start), and Chinese/Japanese equivalents such as 所以, 因此, れば, なら;
- on the comma that ends a conditional or temporal clause ("If X, ...", "Once Y, ..."),
  where the main clause is about to start;
- weakly on other commas.
Everything else is 0. Conditional openers themselves ("if", "when") are slightly positive.
"""
from collections.abc import Mapping

READS = ()

CONSEQUENCE = {"then", "so", "therefore", "thus", "hence", "consequently", "accordingly", "thereby"}
CONSEQUENCE_OTHER = {"所以", "因此", "于是", "从而", "那么", "故", "だから", "ので", "れば", "たら", "なら"}
CLAUSE_OPENERS = {"if": 2.5, "when": 2.5, "once": 3.0, "whenever": 2.5, "unless": 2.0, "after": 2.0,
                  "since": 2.0, "as": 1.0, "because": 1.5, "given": 1.0}
COMMAS = {",", "，", "、"}
LINKS = {",", "，", "、", "and", "but", "(", ")", "),", "\n", "."}
BASE_COMMA = -0.2
MARKER = -3.0
OPENER = 0.3


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    opener, words, prev_doc = (None, 0, None) if carry is None else carry
    if doc != prev_doc:
        opener, words = None, 0
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else "\n"
    w = tok.strip().lower()
    value = 0.0
    if any(c in tok for c in ".!?;\n"):
        opener, words = None, 0
    elif w in CONSEQUENCE:
        value = MARKER if prev in LINKS else MARKER / 3
        opener, words = None, 0
    elif w in CONSEQUENCE_OTHER:
        value = MARKER
        opener, words = None, 0
    elif w in COMMAS:
        value = BASE_COMMA
        if opener is not None:
            value = -CLAUSE_OPENERS[opener] if words <= 15 else -0.5
        opener, words = None, 0
    else:
        if w in CLAUSE_OPENERS:
            value = OPENER
        if opener is None and w in CLAUSE_OPENERS:
            opener, words = w, 0
        elif opener is not None:
            words += 1
    return (opener, words, doc), float(value)

"""Totality and sameness words in the determiner slot of a noun phrase.

What it does: this component goes strongly negative on a word that says a noun is taken
whole, or is the very same one, when the word sits right after a determiner or possessive:
"the whole year", "a full day", "the entire city", "on the same day", "the actual cost",
"their own house". The strongest are whole and entire; full and same come next; complete,
total and the own/original/actual group are weaker. The same words used as a predicate
("is the same", "stay the same", "is full of") move it much less. A code-fence opener
(```, which starts a code block) also drives it negative. Other tokens predict 0.

The program is a short word list in tiers, scaled by whether a determiner came before.
Translations of the same words (ganz, весь, 整个, 同じ, ...) fall in the same tiers.
"""

READS = ()

# The noun taken in its entirety: "the whole", "the entire", "整个", "ganze".
WHOLE_ENTIRE = {
    " whole", " entire", " Whole", "整个", "整個", "整", " ganz", " ganze", " hele",
    " весь", " всей", " всю", " вся", " todo", " toda", " tout", " toute", " toàn", " intero",
}
# "The full": a noun filled up or complete.
FULL = {" full", " Full", "全", "全部", " полно"}
# Identity with something already mentioned: "the same", "that same".
SAME = {
    " same", " Same", " mesmo", " mismo", " misma", " mesma", " stesso", " aynı", " même",
    "同じ", "同一", "同", " же", " самом", " самого",
}
# Weaker completeness words: "the complete", "the total", "fully".
COMPLETE = {" complete", " total", " fully", " completely", " entirely", "完整", "完全"}
# The noun's own or present state: "its own", "the original", "the actual", "the current".
SELF_STATE = {
    " own", " original", " actual", " single", " real", " current", " exact", " present",
    " existing", " pure", " overall", " normal", " individual", " former", " true",
    " regular", " plain", " main", " general", " native", " raw",
    # Chinese "this / original": 本网站, 原来的, 该公司
    "本", "原", "该",
}
FENCE = "```"

VALUE = {"whole": -16.0, "full": -12.0, "same": -8.0, "complete": -4.0, "self": -3.0, "fence": -10.0}
DETERMINERS = {
    "the", "a", "an", "this", "that", "these", "those", "his", "her", "its",
    "their", "our", "my", "your", "every", "each",
}
OFF_CONTEXT = 0.6  # the same words not right after a determiner, e.g. "is the same"


def _kind(token):
    if token == FENCE:
        return "fence"
    for name, words in (
        ("whole", WHOLE_ENTIRE), ("full", FULL), ("same", SAME),
        ("complete", COMPLETE), ("self", SELF_STATE),
    ):
        if token in words:
            return name
    return None


def step(carry, prefix, upstream):
    kind = _kind(prefix.token_strings[-1])
    if kind is None:
        return carry, 0.0
    value = VALUE[kind]
    if kind == "fence":
        return carry, value
    same_document = (
        len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    previous = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if same_document and previous in DETERMINERS:
        return carry, value
    return carry, value * OFF_CONTEXT

"""Component L15 MLP hidden unit 5558 (its down_proj column), read as an activation.

Its activation is almost exactly this MLP hidden unit's value (about 60% of its
input direction is that one unit). That value is mostly small, with occasional
strong negative spikes. Simple word-level rules explain very little of it: this
program is a rough guide, not a full account.

Rules, from scanning ~8M training tokens:
- closing quotation marks (',"', '."', '?"', '”') are strongly negative;
- verbs that hand something to or act on a person (give, tell, send, take, ask,
  put ...) are moderately negative, as are other verbs and prepositions;
- Han characters are mildly negative;
- everything else sits near the average.
"""

from collections.abc import Mapping

import regex
import wordnet

READS: tuple[str, ...] = ()

CLOSING_QUOTES = {',"', ',”', '."', '?"', '”', '"', '.”', '?”', '!"', '。”'}
TRANSFER_VERBS = {
    "give", "gave", "given", "tell", "told", "send", "sent", "pay", "paid",
    "take", "took", "taken", "bring", "brought", "hold", "held", "pick",
    "hire", "teach", "taught", "remind", "kill", "hit", "ask", "asked",
    "put", "call", "called", "offer", "offered",
}
PREPOSITIONS = {"to", "by", "for", "with", "from", "on", "in", "at", "into", "of"}


def _predict(token: str) -> float:
    word = token.strip().lower()
    if token in CLOSING_QUOTES:
        return -0.9
    if regex.search(r"\p{Han}", token):
        return -0.14
    if token.startswith(" ") and word in TRANSFER_VERBS:
        return -0.9
    if token.startswith(" ") and word.isalpha() and "verb" in wordnet.parts_of_speech(word):
        return -0.12
    if token.startswith(" ") and word in PREPOSITIONS:
        return -0.11
    return -0.03


def step(carry, prefix, upstream: Mapping):
    return carry, _predict(prefix.token_strings[-1])

"""Predicate-completion detector for layers.15.mlp.down_proj component 5561.

What it is: a weak, mostly lexical signal. The component reads mainly MLP hidden
unit 5561 of layer 15. Its activation is positive on a word that completes a
predicate (a participle or adjective after "is", "was", "be", "been" or "not", as in
"was lifted", "is not satisfied"), and on particles and object pronouns that end a
verb phrase ("it", "them", "up", "out", "again"). It is negative on words that open a
continuation: the infinitive "to", be-verbs themselves, modals, prepositions,
conjunctions, "not"/"still", and -ing forms (verbs that take an object next).

The weights are rounded group means fitted on 4096 training rows (about 2M tokens).
Most of the variance is not captured by any word class; this explains only a small
share of it.
"""

from collections.abc import Mapping
import re

READS: tuple[str, ...] = ()

BE = {"is", "are", "was", "were", "be", "been", "being", "am"}
NEGATION = {"not", "never", "no", "still"}
CONTINUE = {"to", "of", "in", "with", "from", "into", "on", "by", "at", "for", "as",
            "about", "and", "or", "if", "that", "should", "will", "can", "could",
            "would", "may", "might", "must"}
DETERMINERS = {"the", "a", "an", "this", "that", "there", "they", "he", "she", "we",
               "i", "you", "it", "them", "his", "her", "its", "their", "my", "your", "our"}
PARTICLES = {"it", "them", "up", "out", "down", "off", "again", "together", "away", "back"}


def _word(text: str) -> str:
    return text.strip().lower()


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    alpha = re.fullmatch(r"[a-z]+", word) is not None

    if word in BE or word in CONTINUE or word in NEGATION:
        value = -0.17
    elif word in PARTICLES:
        value = 0.53
    elif not alpha:
        value = 0.03
    elif prev in BE or prev in NEGATION:
        # predicate complement: "was removed", "is not satisfied"
        value = -0.14 if word.endswith("ing") or word in DETERMINERS else 0.55
    elif word.endswith("ed") and len(word) > 3:
        value = 0.10
    elif word.endswith("ing") and len(word) > 4:
        value = -0.16
    else:
        value = 0.06
    return None, value

"""Layer 15 MLP down-projection, component 5562: a first/second-person pronoun detector.

What it does: the activation goes negative on pronouns that speak for the writer or
address the reader. "I", "me", "my", "we", "our", "us" (and 我, я, мы, наш, wir, nous, ...)
are strongly negative; "you", "your" (and 你, ты, вы, du, vous, ...) less so. Inside an
assistant reply the pronouns are more negative still (e.g. the "I" in "I'm sorry, but I
cannot"). The word right after a first-person pronoun ("I [have]", "we [will]") is also
negative. Other tokens are near zero, with diffuse noise that this short program does not
model; its variance explained is about 0.07 to 0.08, mostly from the pronoun tokens.

The values are rounded group means fitted on training rows, in activation units.
"""

READS = ()

FIRST_PERSON = {
    "i", "me", "my", "mine", "myself", "we", "us", "our", "ours", "ourselves",
    "我", "我们", "我們", "我的", "я", "мы", "меня", "мне", "мой", "наш",
    "ich", "mich", "mein", "wir", "uns", "je", "nous", "moi", "eu",
}
SECOND_PERSON = {
    "you", "your", "yours", "yourself", "你", "您", "你的", "ты", "вы", "ваш",
    "du", "sie", "tu", "vous", "usted",
}
# Values for the current token, and for the token after a pronoun.
PRONOUN_NOW = {"first": (-1.5, -3.5), "second": (-1.1, -1.1)}  # (outside, inside assistant)
AFTER_PRONOUN = {"first": (-0.6, -2.0), "second": (-0.25, -0.25)}


def _word(token):
    return token.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    # carry: (inside an assistant reply, previous token's word, document id)
    new_doc = len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        in_assistant, previous = False, ""
    else:
        in_assistant, previous = carry[0], carry[1]

    token = prefix.token_strings[-1]
    if token == "<|im_end|>":
        in_assistant = False
    elif previous == "<|im_start|>":
        in_assistant = token.strip() == "assistant"

    word = _word(token)
    inside = 1 if in_assistant else 0
    value = 0.0
    if word in FIRST_PERSON:
        value = PRONOUN_NOW["first"][inside]
    elif word in SECOND_PERSON:
        value = PRONOUN_NOW["second"][inside]
    elif _word(previous) in FIRST_PERSON:
        value = AFTER_PRONOUN["first"][inside]
    elif _word(previous) in SECOND_PERSON:
        value = AFTER_PRONOUN["second"][inside]

    return (in_assistant, token, prefix.document_ids[-1]), value
